export function renderInline(text, definitions) {
  const out = []
  for (let i = 0; i < text.length; i += 1) {
    const char = text[i]

    // Handle escapes: backslash before escapable characters
    if (char === '\\' && i + 1 < text.length && ESCAPABLE.includes(text[i + 1])) {
      out.push(escapeText(text[i + 1]))
      i += 1
      continue
    }

    // Handle code spans: backtick pairs with escaped content
    if (char === '`') {
      const close = text.indexOf('`', i + 1)
      if (close !== -1) {
        const content = text.slice(i + 1, close)
        out.push(`<code>${escapeText(content)}</code>`)
        i = close
        continue
      }
    }

    // Handle strong: ** pairs
    if (char === '*' && text[i + 1] === '*') {
      const close = text.indexOf('**', i + 2)
      if (close !== -1) {
        const content = text.slice(i + 2, close)
        out.push(`<strong>${renderInline(content, definitions)}</strong>`)
        i = close + 1
        continue
      }
    }

    // Handle emphasis: * pairs
    if (char === '*') {
      const close = text.indexOf('*', i + 1)
      if (close !== -1) {
        const content = text.slice(i + 1, close)
        out.push(`<em>${renderInline(content, definitions)}</em>`)
        i = close
        continue
      }
    }

    // Handle links: [text](url), [text][label], [text][]
    if (char === '[') {
      const link = readLink(text, i, definitions)
      if (link !== undefined) {
        out.push(`<a href="${escapeAttribute(link.url)}">${renderInline(link.inner, definitions)}</a>`)
        i = link.next - 1
        continue
      }
    }

    // Default: escape text for HTML
    out.push(escapeText(char))
  }

  return out.join('')
}"}

